import pytest
from target_module import calculate_refund

def test_case_1():
    result = calculate_refund(100, 0, False)
    assert result == {"status": "ok", "refund": 100.0}

def test_case_2():
    result = calculate_refund(100, 7, False)
    assert result == {"status": "ok", "refund": 100.0}

def test_case_3():
    result = calculate_refund(100, 14, False)
    assert result == {"status": "ok", "refund": 50.0}

def test_case_4():
    result = calculate_refund(100, 30, False)
    assert result == {"status": "ok", "refund": 100.0}

def test_case_5():
    result = calculate_refund(100, -1, False)
    assert result == {"status": "error", "refund": 0.0}

def test_case_6():
    result = calculate_refund(100, 0, True)
    assert result == {"status": "ok", "refund": 100.0}

def test_case_7():
    result = calculate_refund(100, 7, True)
    assert result == {"status": "ok", "refund": 100.0}

def test_case_8():
    result = calculate_refund(100, 14, True)
    assert result == {"status": "ok", "refund": 50.0}

def test_case_9():
    result = calculate_refund(100, 30, True)
    assert result == {"status": "ok", "refund": 100.0}

def test_case_10():
    result = calculate_refund(100, 31, False)
    assert result == {"status": "ok", "refund": 0.0}

reference:
def calculate_refund(price, days_since_purchase, is_defective):
    if days_since_purchase < 0:
        return {'status': 'error', 'refund': 0}
    elif is_defective:
        if days_since_purchase <= 30:
            return {'status': 'success', 'refund': price}
        elif days_since_purchase <= 60:
            return {'status': 'partial', 'refund': price / 2}
        else:
            return {'status': 'partial', 'refund': 0}
    else:
        if days_since_purchase <= 7:
            return {'status': 'success', 'refund': price}
        elif days_since_purchase <= 14:
            return {'status': 'partial', 'refund': price / 2}
        else:
            return {'status': 'partial', 'refund': 0}

