def shipping_fee(weight_kg, is_express):
    if weight_kg <= 0:
        return {'status': 'error', 'fee': 0}
    base_fee = 5.0
    additional_fee = max(0, (weight_kg - 1) // 1) * 2.0
    fee = base_fee + additional_fee
    if is_express:
        fee *= 1.5
    fee = min(fee, 40.0)
    return {'status': 'ok' if fee <= 40.0 else 'error', 'fee': fee}

