def weekly_pay(hours, hourly_rate):
    if hours < 0 or hourly_rate <= 0:
        return {'status': 'error', 'pay': 0}
    elif hours <= 40:
        return {'status': 'ok', 'pay': hours * hourly_rate}
    elif hours <= 60:
        return {'status': 'ok', 'pay': 40 * hourly_rate + (hours - 40) * hourly_rate * 1.5}
    else:
        return {'status': 'ok', 'pay': 40 * hourly_rate + (60 - 40) * hourly_rate * 1.5 + (hours - 60) * hourly_rate * 2}

