def parking_fee(minutes):
    if minutes < 0:
        return {'status': 'error', 'fee': 0}
    elif minutes <= 30:
        return {'status': 'free', 'fee': 0}
    else:
        hours = minutes // 60
        minutes %= 60
        fee = 2.0 * (hours + 1) * minutes
        return {'status': 'paid', 'fee': min(fee, 20.0)}

