def letter_grade(score):
    if score < 0 or score > 100:
        return {'status': 'error', 'grade': 'N/A'}
    elif score >= 90:
        return {'status': 'pass', 'grade': 'A'}
    elif score >= 80:
        return {'status': 'pass', 'grade': 'B'}
